-- Katalog bahan baku lengkap dari SELURUH foto struk (Juli-November 2026).
-- Sumber: reports/inventaris-lengkap-2026 (analyze.py -> semua-nama-bahan.csv,
-- aksi-bahan.csv). Bukti OCR: pos.financial_transactions.metadata.scanItems,
-- pos.expense_receipt_items, pos.expense_receipt_ai_runs.result.items.
--
-- Aditif dan idempoten: tidak menghapus bahan, tidak mengganti nama bahan lama,
-- tidak menyentuh riwayat stok/resep/pesanan. Hanya menambah bahan baru,
-- memperkaya alias, mencatat audit, dan menyegarkan antrean review kandidat.

BEGIN;

SELECT set_config('yumi.allow_manual_material_create', 'on', true);
SELECT set_config('yumi.allow_inventory_catalog_write', 'on', true);

-- 0. Jalur migrasi katalog pada guard mode stok manual -------------------
CREATE OR REPLACE FUNCTION pos.guard_manual_stock_inventory_write()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pos', 'public', 'pg_catalog'
AS $function$
BEGIN
  IF current_setting('yumi.allow_inventory_catalog_write', true) = 'on' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;
  IF pos.current_inventory_stock_mode() = 'manual' THEN
    IF TG_OP = 'INSERT' AND current_setting('yumi.allow_manual_material_create', true) = 'on' THEN
      RETURN NEW;
    END IF;
    RAISE EXCEPTION USING ERRCODE = 'P0001', MESSAGE = 'Mode stok manual aktif: gunakan halaman Stok Manual untuk memperbarui bahan.';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$;

-- 1. Snapshot sebelum perubahan (sekali saja) ----------------------------
CREATE TABLE IF NOT EXISTS pos.inventory_allreceipts_snapshot AS
SELECT i.*, now() AS snapshot_at FROM pos.inventory i;
COMMENT ON TABLE pos.inventory_allreceipts_snapshot IS
  'Salinan pos.inventory sebelum pembaruan katalog seluruh struk 2026.';

-- 2. Bahan baku baru -----------------------------------------------------
WITH baru(ingredient_name, unit, display_unit, aliases, note) AS (
  VALUES
    ('Cabe Besar', 'kg', 'kg', '["Cabe Besar", "C. merah B.", "C. merah besar", "Cabai Merah Besar", "Cabe merah besar"]'::jsonb, 'Cabe merah besar, berbeda dari cabe keriting/rawit.'),
    ('Caisim', 'kg', 'kg', '["Caisim"]'::jsonb, 'Sayur caisim/sawi hijau, dibeli per kg.'),
    ('Cumi', 'kg', 'kg', '["Cumi"]'::jsonb, 'Cumi segar, dibeli per kg.'),
    ('Freshmilk Cimory 950ml', 'pcs', 'liter', '["Freshmilk Cimory 950ml", "Cimory Full Cream Milk"]'::jsonb, 'Susu segar Cimory Full Cream 950ml; merek berbeda dari Diamond/Greenfield.'),
    ('Kikil Sapi', 'kg', 'kg', '["Kikil Sapi"]'::jsonb, 'Kikil/kulit sapi putih, dibeli per kg.'),
    ('Tempe', 'pcs', 'pcs', '["Tempe"]'::jsonb, 'Tempe papan, dibeli per pcs.')
)
INSERT INTO pos.inventory (
  source_id, ingredient_name, unit, quantity, low_stock_threshold,
  display_unit, aliases, category, unit_status, creation_time, raw
)
SELECT
  'inv_nov26_' || substr(md5(lower(btrim(b.ingredient_name))), 1, 24),
  b.ingredient_name,
  b.unit,
  0,
  0,
  b.display_unit,
  b.aliases,
  'kitchen',
  'AMBIGUOUS',
  extract(epoch FROM now()) * 1000,
  jsonb_build_object(
    'source', 'receipt-images-2026-07..11',
    'report', 'reports/inventaris-lengkap-2026',
    'note', b.note
  )
FROM baru b
WHERE NOT EXISTS (
  SELECT 1 FROM pos.inventory i
  WHERE lower(btrim(i.ingredient_name)) = lower(btrim(b.ingredient_name))
)
ON CONFLICT (source_id) DO NOTHING;

INSERT INTO pos.inventory_catalog_update_log (inventory_source_id, ingredient_name, action, detail)
SELECT i.source_id, i.ingredient_name, 'material_created',
       jsonb_build_object('unit', i.unit, 'displayUnit', i.display_unit)
FROM pos.inventory i
WHERE i.source_id LIKE 'inv_nov26_%'
  AND NOT EXISTS (
    SELECT 1 FROM pos.inventory_catalog_update_log l
    WHERE l.inventory_source_id = i.source_id AND l.action = 'material_created'
  );

-- 3. Perkaya alias tanpa menghapus alias lama ---------------------------
CREATE OR REPLACE FUNCTION pg_temp.merge_alias(p_existing jsonb, p_add text[])
RETURNS jsonb
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT coalesce(jsonb_agg(a ORDER BY ord), '[]'::jsonb)
  FROM (
    SELECT DISTINCT ON (lower(btrim(a))) a, ord
    FROM (
      SELECT value AS a, row_number() OVER () AS ord
      FROM jsonb_array_elements_text(coalesce(p_existing, '[]'::jsonb))
      UNION ALL
      SELECT x AS a, 100000 + row_number() OVER () AS ord
      FROM unnest(p_add) AS x
    ) merged
    WHERE btrim(a) <> ''
    ORDER BY lower(btrim(a)), ord
  ) dedup;
$$;

